'use client';
import { useEffect, useState } from 'react';
import { getUsers } from '@/lib/db';

export function UserList() {
  const [users, setUsers] = useState<{ id: number }[]>([]);
  useEffect(() => {
    getUsers().then(setUsers);
  }, []);
  return <ul>{users.map((u) => <li key={u.id}>{u.id}</li>)}</ul>;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
async function getUser() { await sleep(300); return 'user'; }
async function getPosts() { await sleep(300); return 'posts'; }

export default async function Page() {
  let t = Date.now();
  await getUser();
  await getPosts();
  const a = Math.round((Date.now() - t) / 100) * 100;

  t = Date.now();
  await Promise.all([getUser(), getPosts()]);
  const b = Math.round((Date.now() - t) / 100) * 100;

  return <p>{a} {b}</p>;
}

